            - (self.group3() * Simd32x3::from(other[e4]).with_w(other[e5]))
            - (other.group1().yzxy() * self.group9().zxy().with_w(self[e25]))
            - (other.group1().wwwz() * self.group5().with_w(self[e35]))
            - (Simd32x2::from(self[scalar]) * other.group3().xy()).with_zw(other[e2] * self[e23], other[e315] * self[e31])
            - (other.group3().zxz() * self.group5().yz().with_z(self[scalar])).with_w(0.0);
        let geometric_anti_product_g10 = (other[e321] * self[e1234]) + (other[e4] * self[scalar]) + (other[e4] * self[e45])
            - (other[e423] * self[e23])
            - (other[e423] * self[e4235])
            - (other[e431] * self[e31])
            - (other[e431] * self[e4315])
            - (other[e412] * self[e12])
            - (other[e412] * self[e4125])
            - (other[e415] * self[e41])
            - (other[e425] * self[e42])
            - (other[e435] * self[e43])
            - (other[e1] * self[e41])
            - (other[e2] * self[e42])
            - (other[e3] * self[e43]);
        let anti_reverse_g3 = self.group3() * Simd32x4::from(-1.0);
        let anti_reverse_g4 = self.group4() * Simd32x3::from(-1.0);
        let anti_reverse_g5 = self.group5() * Simd32x3::from(-1.0);
