                - (Simd32x2::from(geometric_anti_product_g8[0]) * Simd32x2::from([anti_reverse_g4[0], anti_reverse_g7[0]]))
                - (Simd32x2::from(geometric_anti_product_g8[1]) * Simd32x2::from([anti_reverse_g4[1], anti_reverse_g7[1]]))
                - (Simd32x2::from(geometric_anti_product_g8[2]) * Simd32x2::from([anti_reverse_g4[2], anti_reverse_g7[2]]))
                - (Simd32x2::from(anti_reverse_g3[3]) * Simd32x2::from([geometric_anti_product_g6[3], geometric_anti_product_g3[3]]))
